/// <summary>
/// MPJ_28152_CSD_Fulfilment
/// Creating a class instead of a map like LedgerJournalEntityBase as we are only managing transfer orders
/// </summary>
class METInventTransferOrderEntityBase
{
}

Method.Source:
    /// <summary>
    /// Updates the user-provided journal number with one generated from the proper number sequence.
    /// </summary>
    /// <param name = "_dmfDefinitionGroupExecution">A data management framework definition group being executed.</param>
    /// <returns><c>METInventTransferOrderEntityBaseTmp</c> populated with old to new transfer order number mapping</returns>
    public static METInventTransferOrderEntityBaseTmp generateJournalNumbers(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
    {
        METInventTransferOrderHeaderStaging staging;
        
        ttsbegin;

        NumberSequenceReference numberSequenceReference = NumberSeqReference::findReference(extendedtypenum(InventTransferId));
        NumberSeq journalNumberSeq = NumberSeq::newGetNum(numberSequenceReference, false);

        InventTransferTable existingTransferOrders;

        METInventTransferOrderEntityBaseTmp transferOrderNumberMap;
        RecordInsertList journalBatchNumberMapList = new RecordInsertList(tableNum(METInventTransferOrderEntityBaseTmp), true, true, true, false, false, transferOrderNumberMap);

        while select TransferOrderNumber from staging
            group by TransferOrderNumber
        where staging.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup
            && staging.ExecutionId == _dmfDefinitionGroupExecution.ExecutionId
            && staging.TransferStatus == DMFTransferStatus::NotStarted
        notexists join existingTransferOrders
            where staging.TransferOrderNumber == existingTransferOrders.TransferId
        {
            transferOrderNumberMap.clear();

            transferOrderNumberMap.OldTransferOrderNumber = staging.TransferOrderNumber;
            transferOrderNumberMap.NewTransferOrderNumber = journalNumberSeq.num();

            journalBatchNumberMapList.add(transferOrderNumberMap);
        }

        journalBatchNumberMapList.insertDatabase();

        ttscommit;

        return transferOrderNumberMap;
    }

    /// <summary>
    /// Determines if the manual property is true for the number sequence assigned to
    /// the <c>JournalBatchNumber</c> field on <c>LedgerJournalTable</c>.
    /// </summary>
    /// <returns>true if the number sequence field manual is set; otherwise, false.</returns>
    internal static boolean isTransferOrderNumberSequenceManual()
    {
        NumberSequenceReference reference = NumberSequenceReference::findByDatatypeAndScope(extendedTypeNum(InventTransferId));
        NumberSequenceTable numberSeq = reference.numberSequenceTable();

        return (numberSeq.Manual == NoYes::Yes);
    }
